package mrpapermoon.whisper.serviceimport kotlinx.coroutines.flow.Flowsealed interface NearbyConnectionEvent {	val endpointId: String	class OnBytesPayloadReceived(override val endpointId: String, val payload: ByteArray): NearbyConnectionEvent	class OnFlowPayloadReceived(override val endpointId: String, val payloadFlow: Flow<ByteArray>): NearbyConnectionEvent	class OnConnection(override val endpointId: String, val imHosting: Boolean): NearbyConnectionEvent	class OnDropConnection(override val endpointId: String): NearbyConnectionEvent	class OnDisconnected(override val endpointId: String): NearbyConnectionEvent}